cd ~/DEV/drive-tools; python3 -I - <<'PY'
import csv, json, subprocess, sqlite3
from concurrent.futures import ThreadPoolExecutor
f='drive-index/rename_2026-10-31_spaces.csv'
rows=[r for r in csv.DictReader(open(f)) if not r['old'].startswith('NordBord_')]
con=sqlite3.connect('file:drive-index/drive.sqlite?mode=ro',uri=True)
print('in index by folder+name:', sum(1 for r in rows if con.execute('select count(*) from files where folder=? and name=?',(r['folder'],r['old'])).fetchone()[0]==1), 'of', len(rows))
def meta(r):
    p=subprocess.run(['gws','drive','files','get','--params',json.dumps({'fileId':r['id'],'fields':'name,shared,ownedByMe,trashed'})],capture_output=True,text=True)
    try: return r, json.loads(p.stdout)
    except ValueError: return r, None
keep=[];held=[]
with ThreadPoolExecutor(6) as ex:
    for r,m in ex.map(meta,rows):
        if m is None: held.append((r,'no_read'))
        elif m.get('trashed') or m.get('name')!=r['old']: held.append((r,'changed:'+str(m.get('name'))))
        elif m.get('shared') or not m.get('ownedByMe',True): held.append((r,'shared'))
        else: keep.append(r)
w=csv.DictWriter(open(f,'w',newline=''),fieldnames=['folder','old','new','id']); w.writeheader(); w.writerows(keep)
print('keep',len(keep))
for r,why in held: print('HELD',why,'|',r['folder'].replace('00_Primary_Storage_Drive/',''),'/',r['old'])
PY

